 if(argc!=2)return 2;CoInitializeEx(nullptr,COINIT_MULTITHREADED);auto root=fs::absolute(argv[1]),home=root/"local_accounts"/std::string(32,'a'),generated=home/"generated",current=generated/"empty";fs::create_directories(current);auto bytes=readFile(root/"fixture.png");std::string owner(64,'a'),channel(32,'b');
